 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r - 1][c] == 2 and grid[r + 1][c] == 2
                    and grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                centers.append((r, c))
    tips = []
    for r, c in centers:
        tips.extend([
            (r - 1, c, 'up'), (r + 1, c, 'down'),
            (r, c - 1, 'left'), (r, c + 1, 'right'),
        ])
    opposite = {'up': 'down', 'down': 'up', 'left': 'right', 'right': 'left'}
    for i, (r1, c1, d1) in enumerate(tips):
        for r2, c2, d2 in tips[i + 1:]:
            if d2 != opposite[d1]:
                continue
            if r1 == r2 and c1 != c2:
                lo, hi = sorted((c1, c2))
                for c in range(lo + 1, hi):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2 and r1 != r2:
                lo, hi = sorted((r1, r2))
                for r in range(lo + 1, hi):
                    if out[r][c1] == 0:
                        out[r][c1] = 1
    return out
